import { randomBytes } from 'node:crypto'
import { existsSync, writeFileSync } from 'node:fs'

/* Writes .env with fresh random secrets for docker compose (npm run setup).
   An existing .env is left alone. */

const file = new URL('../.env', import.meta.url)
if (existsSync(file)) {
  console.log('.env exists already; nothing changed.')
  process.exit(0)
}
const secret = () => randomBytes(32).toString('base64url')
writeFileSync(
  file,
  [
    '# Generated by npm run setup. Keep this file private; it is not committed.',
    '# Postgres takes its password only when it first creates its volume, and',
    '# its port is bound to localhost. For a new server, set one before the',
    '# first `docker compose up` (npm start then needs DATABASE_URL to match):',
    `# POSTGRES_PASSWORD=${secret()}`,
    `APP_SECRET=${secret()}`,
    `HYPER_SNAPSHOT_SECRET=${secret()}`,
    'APP_PORT=4300',
    'DB_PORT=5436',
    '',
  ].join('\n'),
)
console.log('Wrote .env with random secrets.')
